ACTIVITIES={"Outdoor assembly":"बाहरी सभा","Sports period":"खेल अवधि","Classroom activities":"कक्षा गतिविधियाँ","School commute":"स्कूल यात्रा"}
VERDICTS={"Go ahead":"जारी रखें","Modify":"बदलें","Move indoors":"अंदर करें"}
CATEGORIES={"Good":"अच्छा","Satisfactory":"संतोषजनक","Moderate":"मध्यम","Poor":"खराब","Very Poor":"बहुत खराब","Severe":"गंभीर"}
def get_text(language,key,**values): return TEXT.get(language,TEXT["English"]).get(key,TEXT["English"].get(key,key)).format(**values)
def translate_activity(value,language): return ACTIVITIES.get(value,value) if language=="हिन्दी" else value
def translate_verdict(value,language): return VERDICTS.get(value,value) if language=="हिन्दी" else value
def translate_category(value,language): return CATEGORIES.get(value,value) if language=="हिन्दी" else value
